<template>
  <view class="light-page">
    <view class="page-top"><view><text class="eyebrow">小妙的探索航线</text><text class="page-title">光线救援站</text></view><view class="progress-badge"><text class="badge-star">✦</text><text>{{ completed.length }} / 6</text><text class="badge-caption">已点亮</text></view></view>
    <view v-if="error" class="save-error"><text>{{ error }}</text><button v-if="pending.length" @click="retrySave">重试保存</button></view>
    <template v-if="!level">
      <view class="hero">
        <view class="sky-stars"><view v-for="(star,i) in stars" :key="i" class="star" :style="star" /></view>
        <view class="moon" /><view class="orbit orbit-one" /><view class="orbit orbit-two" />
        <text class="hero-tag">今晚，让海湾亮起来</text><text class="hero-title">借一束光，<br />找到回家的方向。</text>
        <text class="hero-copy">旋转小镜子，把光送到灯塔。<br />小妙在等你一起出发。</text>
        <view class="hero-beam" /><view class="hero-island"><view class="big-tower"><view class="tower-roof" /><view class="tower-lamp" /><view class="tower-body" /></view></view>
        <image class="hero-miao" src="/static/puzzle/robot-miao.png" mode="aspectFit" />
        <view class="hero-bottom"><text>6 座灯塔</text><text>不限时 · 随时重试</text></view>
      </view>
      <view class="how-to"><view><text class="step-number">1</text><text>点镜子转向</text></view><text class="step-arrow">→</text><view><text class="step-number">2</text><text>发射看路线</text></view><text class="step-arrow">→</text><view><text class="step-number">3</text><text>点亮灯塔</text></view></view>
      <view class="section-heading"><text>选一座灯塔出发</text><text class="section-note">每一关都能直接玩</text></view>
      <view class="level-list"><button v-for="(item,index) in levels" :key="item.id" :class="['level-card',{complete:completed.includes(item.id)}]" @click="start(item)"><view class="level-medallion"><text>{{ completed.includes(item.id) ? '✦' : String(index+1).padStart(2,'0') }}</text></view><view class="level-copy"><text class="level-name">{{ item.name }}</text><text class="level-place">{{ item.place }} · {{ item.mirrors.length }} 面镜子</text></view><text class="level-action">{{ completed.includes(item.id) ? '再探索' : '出发' }} ↗</text></button></view>
      <text class="footer">没有倒计时，也不扣分。<br />点亮记录保存在本机，随时可以换个办法再玩。</text>
    </template>
    <template v-else>
      <view class="chapter-row"><text class="chapter">航线 {{ levelIndex+1 }} / 6 · {{ level.place }}</text><button class="text-button" @click="chooseLevels">换座灯塔 ↗</button></view>
      <text class="mission-title">{{ level.name }}</text><text class="mission-copy">{{ level.note }}</text>
      <view :class="['stage-shell',{illuminated:result==='lit'}]">
        <view class="stage-heading"><text><text class="status-dot" /> {{ result==='lit' ? '灯塔已点亮' : playing ? '光正在旅行' : '等待你的光' }}</text><text>点一下镜子，转个方向</text></view>
        <view class="board">
          <view v-for="cell in cells" :key="cell" class="grid-cell" :style="position({x:cell%6,y:Math.floor(cell/6)})" />
          <view v-for="(rock,i) in level.rocks" :key="'rock-'+i" class="object rock-cell" :style="position(rock)"><view class="rock"><view /><view /></view></view>
          <view class="object source-cell" :style="position(level.source)"><view class="source-ring"><view class="source-core" /><text>→</text></view></view>
          <view class="object target-cell" :style="position(level.target)"><view :class="['beacon',{lit:result==='lit'}]"><view class="beacon-halo" /><view class="tower-roof" /><view class="tower-lamp" /><view class="tower-body" /></view></view>
          <button v-for="(mirror,i) in level.mirrors" :key="'mirror-'+i" :aria-label="`镜子 ${i+1}，${faces[i]==='/' ? '右斜' : '左斜'}，点按旋转`" :disabled="playing" :class="['object mirror-cell',{hinted:hintIndex===i}]" :style="position(mirror)" @click="rotate(i)"><view class="mirror-mount"><view :class="['mirror-glass',{slash:faces[i]==='/'}]" /><text class="mirror-label">{{ i+1 }}</text></view></button>
          <view v-for="(segment,i) in segments" :key="shot+'-'+i" class="beam" :style="beamStyle(segment,i)" />
          <view v-if="result==='lit'" class="arrival-spark" :style="position(level.target)">✦</view>
        </view>
        <view class="board-key"><text><text class="key-source">●</text> 起点</text><text><text class="key-mirror">╱</text> 可转动的镜子</text><text><text class="key-target">✦</text> 灯塔</text></view>
      </view>
      <view class="control-card">
        <view v-if="result==='lit'" class="result success"><view class="success-icon">✦</view><view><text class="result-title">{{ completed.length===6 ? '六座灯塔，都亮起来了！' : '这座灯塔，因你亮起来了' }}</text><text class="result-copy">{{ pending.includes(level.id) ? '点亮记录尚未保存，请点上方重试。' : '点亮记录已保存在本机。' }}</text></view></view>
        <view v-else class="result"><text class="result-title">{{ statusTitle }}</text><text class="result-copy">{{ statusCopy }}</text></view>
        <button class="launch" :disabled="playing" @click="fire"><text>{{ playing ? '光正在出发…' : result==='lit' ? '再看一次光的旅行' : '发射光线' }}</text><text v-if="!playing">↗</text></button>
        <view class="secondary-actions"><button :disabled="playing" @click="showHint">✧ 给我一点提示</button><button @click="reset">↺ 重新摆镜子</button></view>
        <view v-if="hint" class="hint-card"><text class="hint-heading">小妙的线索</text><text>{{ hint }}</text></view>
      </view>
      <view v-if="result==='lit'" class="afterglow"><text class="afterglow-label">一起想一想</text><text>光在哪一面镜子上转了弯？<br />先指一指，再讲给家长听。</text><button v-if="levelIndex<levels.length-1" class="next-level" @click="start(levels[levelIndex+1])">去看看下一座灯塔 →</button><button v-else class="next-level" @click="chooseLevels">回到海湾，看看点亮的灯塔 →</button></view>
      <button class="finish-button" @click="home">今天先到这里</button>
      <text class="footer">光路采用方格简化规则，每次进入关卡从头开始。<br />这是一场屏幕里的光线游戏。</text>
    </template>
  </view>
</template>
<script>
import { lightLevels } from '@/data/light-levels.mjs'
import { traceLight, lightHint } from '@/game/light.mjs'
import { lightStore } from '@/services/light.js'
export default {
  data() { return { levels:lightLevels, cells:Array.from({length:36},(_,i)=>i), level:null, faces:[], segments:[], result:'', playing:false, timer:null, shot:0, hint:'', hintIndex:-1, completed:[], pending:[], error:'', stars:[{left:'9%',top:'11%'},{left:'48%',top:'8%'},{left:'61%',top:'31%'},{left:'84%',top:'42%'},{left:'39%',top:'58%'},{left:'13%',top:'74%'},{left:'72%',top:'67%'}] } },
  computed: {
    levelIndex() { return this.levels.findIndex(level=>level.id===this.level?.id) },
    statusTitle() { return this.playing ? '看看光在哪里转弯' : this.result==='edge' ? '光走到了海湾外面' : this.result==='rock' ? '光被小礁石挡住了' : this.result==='loop' ? '光绕成了一个圈' : '先摆镜子，再让光出发' },
    statusCopy() { return this.playing ? '这一束光，会走到灯塔吗？' : this.result ? '沿着光往回看，试着转一面镜子。可以一直试。' : '每点一下镜子，就在两个方向之间切换。' }
  },
  onLoad() { try { this.completed=lightStore.read().completed } catch(error) { this.error='暂时无法读取灯塔记录，仍然可以玩。原记录会保留。' } },
  onHide() { this.cancelFlight() },
  onUnload() { clearTimeout(this.timer) },
  methods: {
    position(point) { return {left:`${point.x*100/6}%`,top:`${point.y*100/6}%`,width:`${100/6}%`,height:`${100/6}%`} },
    beamStyle(segment,index) { const dx=segment.to.x-segment.from.x,dy=segment.to.y-segment.from.y; return {left:`${(segment.from.x+.5)*100/6}%`,top:`${(segment.from.y+.5)*100/6}%`,width:`${Math.hypot(dx,dy)*100/6}%`,transform:`rotate(${Math.atan2(dy,dx)*180/Math.PI}deg)`,animationDelay:`${index*65}ms`} },
    cancelFlight() { clearTimeout(this.timer); this.timer=null; if(this.playing) { this.playing=false; this.segments=[]; this.result='' } },
    start(level) { this.level=level; this.reset(); uni.pageScrollTo({scrollTop:0,duration:0}) },
    reset() { this.cancelFlight(); this.faces=this.level.mirrors.map(mirror=>mirror.face); this.segments=[]; this.result=''; this.hint=''; this.hintIndex=-1 },
    rotate(index) { if(this.playing) return; this.faces[index]=this.faces[index]==='/' ? '\\' : '/'; this.segments=[]; this.result=''; this.hint=''; this.hintIndex=-1 },
    fire() {
      if(this.playing) return
      const trace=traceLight(this.level,this.faces), id=this.level.id
      this.shot++; this.result=''; this.hint=''; this.hintIndex=-1; this.segments=trace.segments; this.playing=true
      this.timer=setTimeout(()=>{ this.playing=false; this.result=trace.status; this.timer=null; if(trace.status==='lit') this.persist(id) },trace.segments.length*65+180)
    },
    showHint() { const hint=lightHint(this.level,this.faces); this.hintIndex=hint && !hint.ready ? hint.index : -1; this.hint=!hint ? '先重新摆镜子，再从起点看看吧。' : hint.ready ? '这条路线已经准备好了！按“发射光线”验证你的想法。' : `看看发光圈里的 ${hint.index+1} 号镜子。把它转成 ${hint.face==='/' ? '右斜 /' : '左斜 \\'} 的样子，再想想光会往哪里走。` },
    persist(id) { try { this.completed=lightStore.mark(id).completed; this.pending=this.pending.filter(item=>item!==id); this.error=this.pending.length ? '还有点亮记录没保存，请重试。' : '' } catch(error) { if(!this.pending.includes(id)) this.pending.push(id); this.error='这次点亮记录没能保存，请在离开前重试。' } },
    retrySave() { for(const id of [...this.pending]) this.persist(id) },
    chooseLevels() { this.cancelFlight(); this.level=null; uni.pageScrollTo({scrollTop:0,duration:0}) },
    home() { uni.switchTab({url:'/pages/home/index'}) }
  }
}
</script>
